const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Commercial tenant retention and churn risk predictor. Analyzes monthly footfall trends, maintenance payment timeliness, utility consumption, and resident satisfaction ratings to predict 90-day renewal likelihood and draft customized lease incentives.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"tenantId":"TEN-048","businessName":"FitZone Studio & Gym","unitNumber":"Clubhouse 2nd Floor","leaseExpiryDate":"2027-02-28","renewalProbability":78.4,"churnRisk":"LOW_TO_MODERATE","healthIndicators":{"footfallTrend":"+14% MoM resident visits","paymentRegularity":"100% on-time maintenance clearance","utilityEfficiency":"Normal HVAC load variance"},"retentionIncentiveProposal":"Offer 3-year renewal with capped 4% annual escalation instead of standard 6%, plus dedicated basement parking slot allocation for training staff.","executiveRecommendation":"High-value community amenity tenant. Initiate renewal discussions 60 days before expiry."}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"tenantId":"TEN-048","businessName":"FitZone Studio & Gym","unitNumber":"Clubhouse 2nd Floor","leaseExpiryDate":"2027-02-28","renewalProbability":78.4,"churnRisk":"LOW_TO_MODERATE","healthIndicators":{"footfallTrend":"+14% MoM resident visits","paymentRegularity":"100% on-time maintenance clearance","utilityEfficiency":"Normal HVAC load variance"},"retentionIncentiveProposal":"Offer 3-year renewal with capped 4% annual escalation instead of standard 6%, plus dedicated basement parking slot allocation for training staff.","executiveRecommendation":"High-value community amenity tenant. Initiate renewal discussions 60 days before expiry."} } }];
}
